#pragma once
#include <juce_audio_utils/juce_audio_utils.h>
#include <vector>
#include <map>
#include <mutex>
struct SequenceNote {int id=0,pitch=60,velocity=100,channel=1;double beat=0,length=.25;};
struct SequenceClip {
 std::vector<SequenceNote> notes;int bars=4,key=-1;bool minor=false;juce::String path;uint64_t revision=1;int nextId=1;bool dirty=false;
 double beats()const{return bars*4.;}
 static bool midi(juce::File f){return f.hasFileExtension("mid;midi");}
 static int inferKey(const std::vector<SequenceNote>& notes,bool& minor){double hist[12]{};for(auto n:notes)hist[n.pitch%12]+=n.length*n.velocity;if(notes.empty())return -1;static const double major[]{6.35,2.23,3.48,2.33,4.38,4.09,2.52,5.19,2.39,3.66,2.29,2.88},min[]{6.33,2.68,3.52,5.38,2.60,3.53,2.54,4.75,3.98,2.69,3.34,3.17};double best=-1;int result=0;for(int mode=0;mode<2;++mode)for(int root=0;root<12;++root){double score=0;for(int p=0;p<12;++p)score+=hist[(p+root)%12]*(mode?min[p]:major[p]);if(score>best){best=score;result=root;minor=mode!=0;}}return result;}
 bool fromMidi(juce::MidiFile file){int ppq=file.getTimeFormat();if(ppq<=0)return false;SequenceClip c;double end=0;for(int t=0;t<file.getNumTracks();++t){auto* track=file.getTrack(t);for(int i=0;i<track->getNumEvents();++i){auto* e=track->getEventPointer(i);auto m=e->message;end=juce::jmax(end,m.getTimeStamp()/ppq);if(m.isKeySignatureMetaEvent()){static const int major[]{0,7,2,9,4,11,6,1};int sf=m.getKeySignatureNumberOfSharpsOrFlats();c.minor=!m.isKeySignatureMajorKey();int k=sf>=0?major[juce::jlimit(0,7,sf)]:((12-(major[juce::jlimit(0,7,-sf)]))%12);c.key=(k+(c.minor?9:0))%12;}if(!m.isNoteOn()||!e->noteOffObject)continue;double b=m.getTimeStamp()/ppq,d=e->noteOffObject->message.getTimeStamp()/ppq-b;if(b<0||d<=0||!std::isfinite(b)||!std::isfinite(d))continue;if(c.notes.size()>=8192)return false;c.notes.push_back({c.nextId++,m.getNoteNumber(),(int)m.getVelocity(),m.getChannel(),b,d});}}
 if(c.notes.empty())return false;if(end>512*4)return false;c.bars=juce::jlimit(1,512,(int)std::ceil((end-1e-7)/4));if(c.key<0)c.key=inferKey(c.notes,c.minor);c.revision=revision+1;*this=std::move(c);return true;}
 bool load(juce::File f){if(f.getSize()>8*1024*1024)return false;auto stream=f.createInputStream();juce::MidiFile file;if(!stream||!file.readFrom(*stream))return false;if(!fromMidi(file))return false;path=f.getFullPathName();return true;}
 juce::MidiFile midiFile()const{juce::MidiMessageSequence s;if(key>=0){int sf=0;double best=99;for(int a=-7;a<=7;++a){int major=(a*7%12+12)%12,k=(major+(minor?9:0))%12;if(k==key&&std::abs(a)<best){best=std::abs(a);sf=a;}}s.addEvent(juce::MidiMessage::keySignatureMetaEvent(sf,minor),0);}s.addEvent(juce::MidiMessage::timeSignatureMetaEvent(4,4),0);for(auto n:notes)if(n.beat<beats()){s.addEvent(juce::MidiMessage::noteOn(n.channel,n.pitch,(juce::uint8)n.velocity),n.beat*960);s.addEvent(juce::MidiMessage::noteOff(n.channel,n.pitch),juce::jmin(beats(),n.beat+n.length)*960);}s.addEvent(juce::MidiMessage::endOfTrack(),beats()*960);s.updateMatchedPairs();juce::MidiFile file;file.setTicksPerQuarterNote(960);file.addTrack(s);return file;}
 bool save(juce::File f){juce::TemporaryFile temp(f);{auto stream=temp.getFile().createOutputStream();if(!stream||!midiFile().writeTo(*stream))return false;stream->flush();if(stream->getStatus().failed())return false;}if(!temp.overwriteTargetFileWithTemporary())return false;path=f.getFullPathName();dirty=false;return true;}
 void changed(){dirty=true;++revision;}
 void transpose(int delta){if(notes.empty())return;int lo=127,hi=0;for(auto n:notes){lo=juce::jmin(lo,n.pitch);hi=juce::jmax(hi,n.pitch);}delta=juce::jlimit(-lo,127-hi,delta);for(auto& n:notes)n.pitch+=delta;if(key>=0)key=(key+delta%12+12)%12;changed();}
 static double snapped(double beat,double grid,bool free){return free?beat:std::round(beat/grid)*grid;}
 void write(juce::XmlElement& root)const{auto* x=root.createNewChildElement("sequence");x->setAttribute("bars",bars);x->setAttribute("key",key);x->setAttribute("minor",minor);x->setAttribute("path",path);for(auto n:notes){auto* e=x->createNewChildElement("note");e->setAttribute("pitch",n.pitch);e->setAttribute("velocity",n.velocity);e->setAttribute("channel",n.channel);e->setAttribute("beat",n.beat);e->setAttribute("length",n.length);}}
 void read(const juce::XmlElement* x){if(!x){*this={};return;}SequenceClip c;c.bars=juce::jlimit(1,512,x->getIntAttribute("bars",4));c.key=juce::jlimit(-1,11,x->getIntAttribute("key",-1));c.minor=x->getBoolAttribute("minor");c.path=x->getStringAttribute("path");for(auto* e:x->getChildIterator()){double b=e->getDoubleAttribute("beat"),d=e->getDoubleAttribute("length");if(e->hasTagName("note")&&c.notes.size()<8192&&std::isfinite(b)&&std::isfinite(d)&&b>=0&&d>0)c.notes.push_back({c.nextId++,juce::jlimit(0,127,e->getIntAttribute("pitch")),juce::jlimit(1,127,e->getIntAttribute("velocity",100)),juce::jlimit(1,16,e->getIntAttribute("channel",1)),b,juce::jmin(d,2048.)});}c.revision=revision+1;*this=std::move(c);}
 struct FileKeyInfo{juce::int64 stamp=0,size=0;int key=-1;bool minor=false;};
 static FileKeyInfo fileKeyInfo(juce::File f){static std::mutex mutex;static std::map<juce::String,FileKeyInfo> cache;auto stamp=f.getLastModificationTime().toMilliseconds(),size=f.getSize();{std::lock_guard<std::mutex> g(mutex);auto it=cache.find(f.getFullPathName());if(it!=cache.end()&&it->second.stamp==stamp&&it->second.size==size)return it->second;}SequenceClip c;int key=c.load(f)?c.key:-1;FileKeyInfo value{stamp,size,key,c.minor};{std::lock_guard<std::mutex> g(mutex);cache[f.getFullPathName()]=value;}return value;}
 static int fileKey(juce::File f){return fileKeyInfo(f).key;}
};
struct MasterSequenceKey{std::atomic<bool> enabled{false};std::atomic<int> key{0};std::atomic<bool> minor{false};};
